CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),listing_id INTEGER NOT NULL REFERENCES listings(id),booking_id INTEGER REFERENCES bookings(id),verification_type TEXT NOT NULL DEFAULT 'unverified',overall_rating INTEGER NOT NULL,value_rating INTEGER,service_rating INTEGER,safety_rating INTEGER,accessibility_rating INTEGER,title TEXT NOT NULL,body TEXT NOT NULL,travel_type TEXT,date_of_experience TEXT,moderation_status TEXT NOT NULL DEFAULT 'published',moderation_reason TEXT,provider_response TEXT,provider_responded_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reviews_listing_status_idx ON reviews(listing_id,moderation_status,created_at);
CREATE TABLE IF NOT EXISTS review_moderation_events (id INTEGER PRIMARY KEY AUTOINCREMENT,review_id INTEGER NOT NULL REFERENCES reviews(id) ON DELETE CASCADE,actor_user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,reason TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_disputes (id INTEGER PRIMARY KEY AUTOINCREMENT,review_id INTEGER NOT NULL REFERENCES reviews(id),raised_by_user_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',resolution TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
